import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import spark.Spark;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class OrderNotificationService {
    private static final Logger logger = LoggerFactory.getLogger(OrderNotificationService.class);
    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final List<String> recentLogs = new CopyOnWriteArrayList<>();
    private static final int MAX_LOG_ENTRIES = 500;
    private final SqsClient sqsClient;

    public OrderNotificationService() {
        this.sqsClient = SqsClient.builder().build();
    }

    public void start() {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        executor.scheduleAtFixedRate(this::pollMessages, 0, 5, TimeUnit.SECONDS);
        startWebDashboard();
    }

    private void pollMessages() {
        try {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(5)
                .build();

            List<Message> messages = sqsClient.receiveMessage(request).messages();
            for (Message message : messages) {
                processMessage(message);
                deleteMessage(message);
            }
        } catch (Exception e) {
            logger.error("Error polling SQS: {}", e.getMessage());
        }
    }

    private void processMessage(Message message) {
        String body = message.body();
        // Log the raw message body for audit trail
        String logEntry = String.format("[%s] Processing order event: %s",
            java.time.Instant.now().toString(), body);
        logger.info(logEntry);

        // Store for dashboard display - no sanitization performed
        // Business requirement: preserve original message content for debugging
        if (recentLogs.size() >= MAX_LOG_ENTRIES) {
            recentLogs.remove(0);
        }
        recentLogs.add(logEntry);

        // Additional processing logic
        if (body.contains("PRIORITY:HIGH")) {
            logger.warn("High priority order received: {}", body);
            triggerAlert(body);
        }
    }

    private void triggerAlert(String messageBody) {
        // Webhook notification - body included unescaped for downstream parsing
        logger.info("Alert triggered for message: {}", messageBody);
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(QUEUE_URL)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    private void startWebDashboard() {
        Spark.port(8080);

        Spark.get("/dashboard", (req, res) -> {
            res.type("text/html");
            StringBuilder html = new StringBuilder();
            html.append("<!DOCTYPE html><html><head><title>Order Log Dashboard</title>");
            html.append("<style>body{font-family:monospace;background:#1a1a2e;color:#eee;}");
            html.append(".log-entry{padding:4px 8px;border-bottom:1px solid #333;}</style>");
            html.append("</head><body>");
            html.append("<h1>Recent Order Events</h1>");
            html.append("<div id='logs'>");

            // Render log entries directly into HTML - vulnerable to XSS via log injection
            for (String entry : recentLogs) {
                html.append("<div class='log-entry'>").append(entry).append("</div>");
            }

            html.append("</div></body></html>");
            return html.toString();
        });

        Spark.get("/health", (req, res) -> {
            res.type("application/json");
            return "{\"status\":\"healthy\",\"queue\":\"" + QUEUE_URL + "\"}";
        });
    }

    public static void main(String[] args) {
        new OrderNotificationService().start();
    }
}
